<script setup>
import{ref}from'vue';const password=ref(''),result=ref(null),error=ref('');
const targets=[{name:'DeepSeek Chat',baseUrl:'https://api.deepseek.com',model:'deepseek-chat',capabilities:['chat'],regions:['CN'],qualityScore:.93,p95LatencyMs:480,inputCostPer1k:.001,outputCostPer1k:.002,remainingTokens:800000,healthy:true,rateLimitAvailable:true},{name:'Fallback Model',baseUrl:'https://api.openai.com/v1',model:'gpt-compatible',capabilities:['chat'],regions:['CN'],qualityScore:.9,p95LatencyMs:620,inputCostPer1k:.003,outputCostPer1k:.006,remainingTokens:500000,healthy:true,rateLimitAvailable:true}];
async function route(){error.value='';try{const body={requestId:'GW-'+Date.now(),prompt:'请总结本月经营风险',requiredCapability:'chat',requiredRegion:'CN',estimatedInputTokens:500,estimatedOutputTokens:300,maxCost:.05,allowFallback:true,execute:false,targets};const r=await fetch('/api/model-gateway/route',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Basic '+btoa('admin:'+password.value)},body:JSON.stringify(body)});if(!r.ok)throw Error('请求失败：'+r.status);result.value=(await r.json()).data;}catch(e){error.value=e.message;}}
</script>
<template><div class="layout"><aside><h2>ZH Model Gateway</h2><p>路由中心</p><p>模型目录</p><p>配额预算</p><p>调用审计</p><a href="https://www.zhuatech.cn/">知华科技</a></aside><main><header><div><small>AI 基础设施 / 生产租户</small><h1>模型路由控制台</h1></div><input v-model="password" type="password" placeholder="管理员密码"></header><section class="cards"><article><b>2</b><span>健康模型</span></article><article><b>CN</b><span>数据驻留区域</span></article><article><b>100%</b><span>调用摘要审计</span></article></section><section class="panel"><div class="title"><div><h2>候选模型</h2><p>按质量、延迟、预算、配额与地域实时决策</p></div><button @click="route">执行路由</button></div><table><thead><tr><th>模型</th><th>质量</th><th>P95 延迟</th><th>剩余配额</th><th>状态</th></tr></thead><tbody><tr v-for="m in targets"><td>{{m.name}}</td><td>{{m.qualityScore}}</td><td>{{m.p95LatencyMs}} ms</td><td>{{m.remainingTokens.toLocaleString()}}</td><td><i>健康</i></td></tr></tbody></table></section><section class="panel result"><h2>路由结果</h2><div v-if="result"><strong>{{result.selectedModel||result.decision}}</strong><p>预计费用：{{result.estimatedCost}} · 降级链：{{result.fallbackModels.join(' → ')||'无'}}</p><ul><li v-for="x in result.excludedReasons">{{x}}</li></ul></div><p v-else>执行后显示选中模型、费用与降级链。</p><em>{{error}}</em></section></main></div></template>
